(()=>{let frame,mode='portrait';function load(){frame?.remove();frame=document.createElement('iframe');frame.src=mode+'.html?v=gridwave-16';frame.title=mode==='portrait'?'Letter portrait':'Star clock';frame.allow='camera';document.body.append(frame);frame.focus()}function toggle(){mode=mode==='portrait'?'clock':'portrait';load()}addEventListener('keydown',e=>{if(e.code==='Digit2'&&!e.repeat){e.preventDefault();toggle()}});addEventListener('message',e=>{if(e.origin===location.origin&&e.source===frame?.contentWindow&&e.data==='switch-mode')toggle()});load()})();